  "CREATE TABLE IF NOT EXISTS `source` (\n\t`id` text PRIMARY KEY NOT NULL,\n\t`kind` text NOT NULL,\n\t`title` text NOT NULL,\n\t`url` text,\n\t`platform` text,\n\t`route` text,\n\t`params` text,\n\t`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) NOT NULL,\n\t`updated_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) NOT NULL,\n\tCONSTRAINT \"ck_source_kind\" CHECK(kind IN ('rss', 'social')),\n\tCONSTRAINT \"ck_source_params\" CHECK(params IS NULL OR json_valid(params)),\n\tCONSTRAINT \"ck_source_shape\" CHECK((kind = 'rss' AND url IS NOT NULL) OR (kind = 'social' AND route IS NOT NULL AND platform IS NOT NULL))\n);\n\nCREATE UNIQUE INDEX IF NOT EXISTS `uq_source_url` ON `source` (`url`) WHERE kind = 'rss';\nCREATE TABLE IF NOT EXISTS `feed_item` (\n\t`id` text PRIMARY KEY NOT NULL,\n\t`source_id` text NOT NULL,\n\t`guid` text NOT NULL,\n\t`title` text NOT NULL,\n\t`summary` text,\n\t`url` text,\n\t`author` text,\n\t`tags` text,\n\t`image` text,\n\t`published_at` text,\n\t`read_at` text,\n\t`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) NOT NULL,\n\t`updated_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) NOT NULL,\n\tFOREIGN KEY (`source_id`) REFERENCES `source`(`id`) ON UPDATE no action ON DELETE cascade,\n\tCONSTRAINT \"ck_feed_item_tags\" CHECK(tags IS NULL OR json_valid(tags))\n);\n\nCREATE UNIQUE INDEX IF NOT EXISTS `uq_feed_item_guid` ON `feed_item` (`source_id`,`guid`);\nCREATE INDEX IF NOT EXISTS `idx_feed_item_unread` ON `feed_item` (`source_id`) WHERE read_at IS NULL;\nCREATE TABLE IF NOT EXISTS `report_run` (\n\t`id` text PRIMARY KEY NOT NULL,\n\t`report_date` text NOT NULL,\n\t`status` text NOT NULL,\n\t`stage` text,\n\t`video_path` text,\n\t`duration_sec` integer,\n\t`error` text,\n\t`finished_at` text,\n\t`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) NOT NULL,\n\t`updated_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) NOT NULL,\n\tCONSTRAINT \"ck_report_run_status\" CHECK(status IN ('running', 'success', 'failed'))\n);\n\nCREATE INDEX IF NOT EXISTS `idx_report_run_date` ON `report_run` (`report_date`,`created_at`);\nCREATE TABLE IF NOT EXISTS `model` (\n\t`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,\n\t`kind` text NOT NULL,\n\t`provider` text NOT NULL,\n\t`name` text NOT NULL,\n\t`api_model` text DEFAULT '' NOT NULL,\n\t`base_url` text DEFAULT '' NOT NULL,\n\t`api_key` text DEFAULT '' NOT NULL,\n\t`context_window` integer,\n\t`max_output` integer,\n\t`usage` text,\n\t`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) NOT NULL,\n\t`updated_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) NOT NULL,\n\tCONSTRAINT \"ck_model_kind\" CHECK(kind IN ('chat', 'embedding', 'ocr')),\n\tCONSTRAINT \"ck_model_usage\" CHECK(usage IS NULL OR (kind = 'chat' AND usage IN ('chat', 'wiki')) OR (kind = 'ocr' AND usage = 'ocr') OR (kind = 'embedding' AND usage = 'embedding'))\n);\n\nCREATE UNIQUE INDEX IF NOT EXISTS `uq_model_identity` ON `model` (`kind`,`provider`,`api_model`,`base_url`);\nCREATE UNIQUE INDEX IF NOT EXISTS `uq_model_usage` ON `model` (`usage`) WHERE usage IS NOT NULL;\nCREATE TABLE IF NOT EXISTS `setting` (\n\t`key` text PRIMARY KEY NOT NULL,\n\t`value` text NOT NULL,\n\t`updated_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) NOT NULL,\n\tCONSTRAINT \"ck_setting_key\" CHECK(key IN ('cookie_cloud', 'platform_cookie', 'remote_connection', 'report_schedule')),\n\tCONSTRAINT \"ck_setting_value\" CHECK(json_valid(value))\n);\n\nCREATE TABLE IF NOT EXISTS `tool_config` (\n\t`name` text PRIMARY KEY NOT NULL,\n\t`enabled` integer DEFAULT false NOT NULL,\n\t`config` text DEFAULT '{}' NOT NULL,\n\tCONSTRAINT \"ck_tool_config_enabled\" CHECK(enabled IN (0, 1)),\n\tCONSTRAINT \"ck_tool_config_json\" CHECK(json_valid(config))\n);\n\nCREATE TABLE IF NOT EXISTS `operation_log` (\n\t`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,\n\t`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')) NOT NULL,\n\t`category` text NOT NULL,\n\t`action` text NOT NULL,\n\t`target_id` text,\n\t`target_name` text NOT NULL,\n\t`detail` text,\n\t`result` text DEFAULT 'success' NOT NULL,\n\tCONSTRAINT \"ck_operation_log_action\" CHECK(action IN ('create', 'update', 'delete', 'import', 'run')),\n\tCONSTRAINT \"ck_operation_log_result\" CHECK(result IN ('success', 'failed'))\n);\n\nCREATE INDEX IF NOT EXISTS `idx_operation_log_created` ON `operation_log` (`created_at`);\nCREATE INDEX IF NOT EXISTS `idx_operation_log_category` ON `operation_log` (`category`,`created_at`);\nCREATE TABLE IF NOT EXISTS `wiki_fts_meta` (\n\t`space_id` text PRIMARY KEY NOT NULL,\n\t`fingerprint` text NOT NULL,\n\t`updated_at` integer NOT NULL\n);\n\n-- drizzle-kit 无法生成的幂等 DDL：FTS5 虚表，以及含表达式的索引\n-- （drizzle-kit 会把 SQL 表达式按逗号拆成多个标识符，生成非法索引定义）\n\nCREATE VIRTUAL TABLE IF NOT EXISTS wiki_fts USING fts5(\n  space_id UNINDEXED,\n  path UNINDEXED,\n  raw_title UNINDEXED,\n  title,\n  body,\n  tokenize = 'unicode61'\n);\n\nCREATE INDEX IF NOT EXISTS idx_feed_item_timeline\n  ON feed_item (coalesce(published_at, created_at), created_at);\n\nCREATE INDEX IF NOT EXISTS idx_feed_item_source_timeline\n  ON feed_item (source_id, coalesce(published_at, created_at));\n";
